import { getList as _getList, remove, up, sync } from "@/api/i6000/unit";
import UnitDeptAddEdit from "./components/unitDept/addedit.vue";
//成本中心页面
export default {
  name: 'i6000Unit',
  components: {
    UnitDeptAddEdit: UnitDeptAddEdit
  },
  data: function data() {
    return {
      tableloading: false,
      queryParams: {},
      page: {
        currentPage: 1,
        pageSize: 20,
        total: 0
      },
      tableData: null,
      showAddEdit: false,
      fromValue: null,
      type: null,
      upLoading: false,
      tbLoading: false
    };
  },
  mounted: function mounted() {
    this.page = {
      currentPage: 1,
      pageSize: 20,
      total: 0
    };
    this.getList();
  },
  methods: {
    getList: function getList() {
      var _this = this;
      this.tableloading = true;
      _getList(this.page.currentPage, this.page.pageSize, this.queryParams).then(function (res) {
        var data = res.data;
        _this.page.total = data.total;
        _this.tableData = data.records;
        _this.tableloading = false;
      });
    },
    handelAdd: function handelAdd() {
      this.type = 'add';
      this.showAddEdit = true;
    },
    handleEdit: function handleEdit(row) {
      this.type = 'edit';
      this.showAddEdit = true;
      this.fromValue = row;
    },
    handelUpdate: function handelUpdate() {
      var _this2 = this;
      this.upLoading = true;
      up().then(function (res) {
        _this2.$message.success('更新成功');
      }).finally(function () {
        _this2.upLoading = false;
      });
    },
    //手动同步按钮
    handelSync: function handelSync() {
      var _this3 = this;
      this.tbLoading = true;
      sync().then(function (res) {
        _this3.$message.success('请求成功');
      }).finally(function () {
        _this3.tbLoading = false;
      });
    },
    handelDelete: function handelDelete(id) {
      var _this4 = this;
      if (id) {
        this.$confirm("确定将选择数据删除?", {
          confirmButtonText: "确定",
          cancelButtonText: "取消",
          type: "warning"
        }).then(function () {
          return remove(id);
        }).then(function () {
          _this4.getList();
          _this4.$message({
            type: "success",
            message: "删除成功!"
          });
        });
      } else {
        if (this.$refs.table.selection.length === 0) {
          this.$message.warning("请选择至少一条数据");
          return;
        }
        this.$confirm("确定将选择数据删除?", {
          confirmButtonText: "确定",
          cancelButtonText: "取消",
          type: "warning"
        }).then(function () {
          var ids = _this4.$refs.table.selection.map(function (item, index) {
            return item.i6000DeptId;
          }).join(',');
          return remove(ids);
        }).then(function () {
          _this4.getList();
          _this4.$message({
            type: "success",
            message: "操作成功!"
          });
        });
      }
    },
    Nindex: function Nindex(index) {
      return index + 1 + (this.page.currentPage - 1) * this.page.pageSize;
    },
    reset: function reset() {
      this.queryParams = {};
      this.page = {
        currentPage: 1,
        pageSize: 20,
        total: 0
      };
      this.getList();
    },
    getTypeColor: function getTypeColor(type) {
      if (type == '0') {
        return '#209141';
      } else if (type == '1') {
        return '#4390F2';
      } else if (type == '2') {
        return '#000000';
      } else if (type == '3') {
        return '#000000';
      }
      return '#000000';
    },
    getTypeName: function getTypeName(type) {
      if (type == '0') {
        return '属性';
      } else if (type == '1') {
        return '配置项';
      } else if (type == '2') {
        return '模型';
      } else if (type == '3') {
        return '字典模型';
      }
    }
  }
};
